select workspace_id, inbox_id, producer_id, operation, idempotency_key, request_hash,
       inbox_state, response_json, in_progress_until, retention_until, created_at
  from aden_inbox
 where workspace_id = #{workspaceId}
   and consumer = 'ADEN_OPERATOR_API'
   and producer_id = #{producerId}
   and operation = #{operation}
   and idempotency_key = #{idempotencyKey}
   for update

mapper.insert:
insert into aden_inbox (
    workspace_id, inbox_id, consumer, producer_id, operation, idempotency_key,
    request_hash, inbox_state, in_progress_until, retention_until, created_at, updated_at
) values (
    #{workspaceId}, #{inboxId}, 'ADEN_OPERATOR_API', #{producerId}, #{operation},
    #{idempotencyKey}, #{requestHash}, 'IN_PROGRESS', #{inProgressUntil},
    #{retentionUntil}, #{createdAt}, #{createdAt}
)

mapper.update:
update aden_inbox
   set inbox_state = 'COMPLETED',
       response_status = #{responseStatus},
       response_json = #{responseJson},
       in_progress_until = null,
       completed_at = #{completedAt},
       updated_at = #{completedAt}
 where workspace_id = #{workspaceId}
   and inbox_id = #{inboxId}
   and inbox_state = 'IN_PROGRESS'

