insert into aden_task (
    workspace_id, task_id, task_type, required_capability, task_state, correlation_id,
    title, input_json, latest_step_no, version, create_idempotency_key,
    create_request_hash, created_by_ruoyi_user_id, created_at, updated_at
) values (
    #{workspaceId}, #{taskId}, #{taskType}, #{requiredCapability}, #{taskState},
    #{correlationId}, #{title}, #{inputJson}, 1, #{version}, #{createIdempotencyKey},
    #{createRequestHash}, #{createdByRuoYiUserId}, #{createdAt}, #{updatedAt}
)

insert into aden_task_step (
    workspace_id, step_id, task_id, step_no, attempt_no, step_type, step_state,
    input_json, version, created_at, updated_at
) values (
    #{workspaceId}, #{stepId}, #{taskId}, #{stepNo}, #{attemptNo},
    'SYNTHETIC_EXECUTION', #{stepState}, #{inputJson}, #{version}, #{createdAt}, #{updatedAt}
)

mapper.select:
select workspace_id, task_id, task_type, required_capability, task_state, correlation_id,
       title, input_json, error_code, version, created_by_ruoyi_user_id, created_at, updated_at
  from aden_task
 where workspace_id = #{workspaceId}
   and task_id = #{taskId}
   for update

mapper.update:
update aden_task
   set task_state = #{nextState},
       version = #{nextVersion},
       updated_at = #{updatedAt}
 where workspace_id = #{workspaceId}
   and task_id = #{taskId}
   and version = #{expectedVersion}
   and task_state = #{expectedState}

update aden_task
   set task_state = 'FAILED',
       version = #{nextVersion},
       error_code = #{reasonCode},
       error_message = '合成任务校验失败',
       updated_at = #{updatedAt}
 where workspace_id = #{workspaceId}
   and task_id = #{taskId}
   and version = #{expectedVersion}
   and task_state = #{expectedState}

update aden_task_step
   set step_state = 'READY',
       version = version + 1,
       updated_at = #{updatedAt}
 where workspace_id = #{workspaceId}
   and task_id = #{taskId}
   and step_no = 1
   and attempt_no = 1
   and step_state = 'PENDING'
   and version = 0

mapper.select:
select step_id from aden_task_step
 where workspace_id = #{workspaceId} and task_id = #{taskId}
   and step_no = 1 and attempt_no = 1 for update

mapper.insert:
insert into aden_runner_delivery (
    workspace_id, delivery_id, task_id, step_id, delivery_state, attempt_no,
    required_capability, priority, available_at, task_package_json,
    task_package_hash, fence_token, latest_receipt_sequence, heartbeat_sequence,
    version, created_at, updated_at
) values (
    #{workspaceId}, #{deliveryId}, #{taskId}, #{stepId}, 'READY', 1,
    'CORE', 100, #{now}, #{taskPackageJson}, #{taskPackageHash},
    0, 0, 0, 0, #{now}, #{now}
)

mapper.update:
update aden_runner_delivery
   set delivery_state = case when delivery_state = 'READY' then 'CANCELED' else delivery_state end,
       cancel_requested_at = case when delivery_state in ('LEASED','RUNNING') then #{now} else cancel_requested_at end,
       completed_at = case when delivery_state = 'READY' then #{now} else completed_at end,
       version = version + 1,
       updated_at = #{now}
 where workspace_id = #{workspaceId}
   and task_id = #{taskId}
   and delivery_state in ('READY','LEASED','RUNNING')

mapper.select:
select count(*) from aden_runner_delivery
 where workspace_id=#{workspaceId} and task_id=#{taskId}
   and delivery_state in ('LEASED','RUNNING')

mapper.update:
update aden_workspace
   set last_event_seq = #{next},
       version = version + 1,
       updated_at = #{updatedAt}
 where workspace_id = #{workspaceId}
   and last_event_seq = #{expected}
   and workspace_status = 'ACTIVE'

